gaoH(){return"\u0628\u06cc\u06af\u06d5\u0695\u06ce\u0646\u06d5\u0648\u06d5 \u0628\u06c6 \u0695\u06cc\u0632\u06d5\u06a9\u06d5"},
gaoD(){return"\u0628\u0695\u06cc\u0627\u0631\u06d5\u06a9\u0627\u0646\u062a \u062a\u06c6\u0645\u0627\u0631 \u06a9\u0631\u0627\u0646"},
