gaoA(){return"\u0695\u0627\u067e\u06c6\u0631\u062a\u06cc \u062f\u0648\u0627\u062a\u0631"},
gaoC(){return"\u0626\u06ce\u0633\u062a\u0627 \u0628\u0648\u06d5\u0633\u062a\u06d5"},
gaoQ(){return"\u062a\u06c6\u0645\u0627\u0631\u06cc \u0645\u0646 \u0648\u06d5\u06a9 \u067e\u06ce\u062f\u0627\u0686\u0648\u0648\u06d5"},
gaoP(){return"\u0626\u06d5\u0645 \u067e\u06d5\u0695\u06d5\u06cc\u06d5 \u062a\u06d5\u0646\u0647\u0627 \u0698\u0645\u0627\u0631\u06d5\u06cc\u06d5: \u0647\u06cc\u0686 \u0646\u0627\u0648\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u0646\u06cc\u06cc\u06d5\u060c \u0648 \u0647\u06cc\u0686 \u0695\u06ce\u06af\u0627\u06cc\u06d5\u06a9 \u0628\u06c6 \u06af\u06d5\u0695\u0627\u0646\u06d5\u0648\u06d5 \u0628\u06c6 \u0626\u06d5\u0631\u06a9\u06ce\u06a9\u06cc \u062f\u0627\u062e\u0631\u0627\u0648."},
gap3(){return"\u06a9\u06c6\u06cc \u0626\u06d5\u0631\u06a9\u06d5 \u067e\u06ce\u062f\u0627\u0686\u0648\u0648\u06d5\u06a9\u0627\u0646"},
gap4(){return"\u0626\u06d5\u0645 \u0647\u06d5\u0641\u062a\u06d5\u06cc\u06d5"},
gap2(){return"\u06af\u06d5\u0695\u06ce\u0646\u062f\u0631\u0627\u0646\u06d5\u0648\u06d5"},
gap1(){return"\u0626\u06d5\u0648 \u06cc\u0627\u0633\u0627\u06cc\u0627\u0646\u06d5\u06cc \u0644\u06d5\u0698\u06ce\u0631\u06cc\u0627\u0646\u062f\u0627 \u06a9\u0627\u0631 \u062f\u06d5\u06a9\u06d5\u06cc\u062a"},
gap_(){return"\u0647\u06d5\u0631 \u062c\u0627\u0631\u06d5 \u06cc\u06d5\u06a9 \u0626\u06d5\u0631\u06a9\u06cc \u06a9\u0631\u0627\u0648\u06d5."},
gaoZ(){return"\u0645\u0627\u0648\u06d5\u06a9\u06d5 \u0663\u0660 \u062e\u0648\u0644\u06d5\u06a9\u06d5\u060c \u067e\u0627\u0634\u0627\u0646 \u0626\u06d5\u0631\u06a9\u06d5\u06a9\u06d5 \u062f\u06d5\u06af\u06d5\u0695\u06ce\u062a\u06d5\u0648\u06d5 \u0628\u06c6 \u0695\u06cc\u0632\u06d5\u06a9\u06d5."},
gaoY(){return"\u0632\u06c6\u0631\u062a\u0631\u06cc\u0646 \u0666\u0660 \u0626\u06d5\u0631\u06a9 \u0644\u06d5 \u0647\u06d5\u0631 \u0662\u0664 \u06a9\u0627\u062a\u0698\u0645\u06ce\u0631\u06ce\u06a9\u062f\u0627."},
gap0(){return"\u0647\u06d5\u0645\u0648\u0648 \u062e\u0648\u06ce\u0646\u062f\u0646\u06d5\u0648\u06d5\u06cc\u06d5\u06a9\u062a \u0646\u06d5\u062e\u06c6\u0634\u06d5\u06a9\u06d5 \u0644\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06cc \u062f\u06d5\u0633\u062a\u06af\u06d5\u06cc\u0634\u062a\u0646\u06cc\u062f\u0627 \u062f\u06d5\u06cc\u0628\u06cc\u0646\u06ce\u062a."},
gaab(){return"\u062a\u06d5\u0646\u06cc\u0627 \u062e\u0627\u0648\u06d5\u0646\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5\u06a9\u06d5 \u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0628\u06af\u06c6\u0695\u06ce\u062a \u06a9\u06ce \u0644\u06ce\u0631\u06d5 \u06a9\u0627\u0631 \u062f\u06d5\u06a9\u0627\u062a \u0648 \u0686\u06cc \u0628\u06c6\u06cc \u0647\u06d5\u06cc\u06d5."},
gaa7(){return"\u0646\u0627\u062a\u0648\u0627\u0646\u06cc\u062a \u062f\u06d5\u0633\u06d5\u06b5\u0627\u062a\u06ce\u06a9 \u0628\u0628\u06d5\u062e\u0634\u06cc\u062a \u06a9\u06d5 \u062e\u06c6\u062a \u0646\u0627\u06cc\u06af\u0631\u06cc\u062a."},
gaae(){return"\u0646\u0627\u062a\u0648\u0627\u0646\u06cc\u062a \u062f\u06d5\u0633\u06d5\u06b5\u0627\u062a\u06cc \u0632\u06cc\u0627\u062a\u0631 \u0628\u06d5 \u062e\u06c6\u062a \u0628\u062f\u06d5\u06cc\u062a. \u06a9\u06d5\u0645\u06a9\u0631\u062f\u0646\u06d5\u0648\u06d5\u06cc \u062f\u06d5\u0633\u06d5\u06b5\u0627\u062a\u06cc \u062e\u06c6\u062a \u0695\u06ce\u06af\u06d5\u067e\u06ce\u062f\u0631\u0627\u0648\u06d5."},
gaa9(){return"\u062f\u06d5\u0633\u062a\u0695\u0627\u06af\u06d5\u06cc\u0634\u062a\u0646 \u0628\u06d5 \u062a\u06c6\u0645\u0627\u0631\u06cc \u0646\u06d5\u062e\u06c6\u0634 \u062a\u06d5\u0646\u06cc\u0627 \u0628\u06c6 \u067e\u0632\u06cc\u0634\u06a9 \u0648 \u0633\u062a\u0627\u0641\u06cc \u067e\u0632\u06cc\u0634\u06a9\u06cc \u067e\u0634\u062a\u0695\u0627\u0633\u062a\u06a9\u0631\u0627\u0648\u06d5\u060c \u0648 \u0626\u06d5\u0645 \u0647\u06d5\u0698\u0645\u0627\u0631\u06d5 \u0644\u06d5\u0648\u0627\u0646\u06d5 \u0646\u06cc\u06cc\u06d5."},
gaac(){return"\u0647\u06d5\u0698\u0645\u0627\u0631\u06cc \u062e\u0627\u0648\u06d5\u0646\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9 \u0646\u0627\u062a\u0648\u0627\u0646\u0631\u06ce\u062a \u0644\u0627\u0628\u0628\u0631\u06ce\u062a \u06cc\u0627\u0646 \u06a9\u06d5\u0645 \u0628\u06a9\u0631\u06ce\u062a\u06d5\u0648\u06d5 \u2014 \u0626\u06d5\u0648\u0633\u0627 \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5\u06a9\u06d5 \u0628\u06ce \u0628\u06d5\u0695\u06ce\u0648\u06d5\u0628\u06d5\u0631 \u062f\u06d5\u0645\u06ce\u0646\u06ce\u062a\u06d5\u0648\u06d5."},
gaad(){return"\u0647\u06cc\u0686 \u0647\u06d5\u0698\u0645\u0627\u0631\u06ce\u06a9 \u0628\u06d5\u0645 \u0646\u0627\u0633\u0646\u0627\u0645\u06d5\u06cc \u062a\u06d5\u0646\u062f\u0631\u0648\u0633\u062a\u06cc\u06cc\u06d5 \u0646\u06d5\u062f\u06c6\u0632\u0631\u0627\u06cc\u06d5\u0648\u06d5. \u0628\u06cc\u067e\u0634\u06a9\u0646\u06d5 \u0648 \u062f\u0648\u0648\u0628\u0627\u0631\u06d5 \u0647\u06d5\u0648\u06b5 \u0628\u062f\u06d5."},
gaa6(){return"\u0626\u06d5\u0645 \u06a9\u06d5\u0633\u06d5 \u067e\u06ce\u0634\u062a\u0631 \u0644\u06d5 \u0633\u062a\u0627\u0641\u06cc \u06a9\u0644\u06cc\u0646\u06cc\u06a9\u06d5\u06a9\u06d5\u062a\u062f\u0627\u06cc\u06d5."},
gaaf(){return"\u0626\u06d5\u0645 \u0626\u06d5\u0646\u062f\u0627\u0645\u06d5 \u0686\u06cc\u062a\u0631 \u0686\u0627\u0644\u0627\u06a9 \u0646\u06cc\u06cc\u06d5. \u0644\u06cc\u0633\u062a\u06d5\u06a9\u06d5 \u0646\u0648\u06ce \u0628\u06a9\u06d5\u0631\u06d5\u0648\u06d5."},
